css:
.loader {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 25%, #e0e7ff 4%, transparent 5%),
    radial-gradient(circle at 50% 75%, #6366f1 4%, transparent 5%),
    radial-gradient(circle at 50% 25%, #6366f1 22%, transparent 23%),
    radial-gradient(circle at 50% 75%, #e0e7ff 22%, transparent 23%),
    linear-gradient(to right, #e0e7ff 50%, #6366f1 50%);
  animation: spin 1.4s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
